for l in lines[2:2+n]:
    p=l.split(); atoms.append((p[0], np.array(list(map(float,p[1:4])))))
P=np.array([p for _,p in atoms]); E=[e for e,_ in atoms]
def d(i,j): return float(np.linalg.norm(P[i]-P[j]))
cons=json.load(open('build/cons.json'))
print("constraint check (target vs actual):")
worst=0
for c in cons:
    i,j=c['atoms']; a=d(i,j); dev=abs(a-c['value'])/c['value']
    worst=max(worst,dev)
    if dev>0.05: print("  VIOL", i,j,c['value'],round(a,3))
print("max deviation %:",round(worst*100,2))
print("Ni-N1:",round(d(0,1),2)," Ni-Ga:",[round(d(0,i),2) for i in (7,8,9,10)]," Ga8-N86:",round(d(8,86),2))
