cov={'H':1.20,'C':1.70,'N':1.55,'Ga':1.87,'Ni':1.63}
best=9e9; bp=None
for i in range(n):
    for j in range(i+1,n):
        dd=d(i,j)
        if dd<1.55 and (E[i]=='H' and E[j]=='H'): 
