    p=l.split(); atoms.append((p[0], np.array(list(map(float,p[1:4])))))
P=np.array([p for _,p in atoms]); E=[e for e,_ in atoms]
def d(i,j): return float(np.linalg.norm(P[i]-P[j]))
print("Ni-N1:",round(d(0,1),2)," Ni-Ga:",[round(d(0,i),2) for i in (7,8,9,10)]," Ga8-N86:",round(d(8,86),2))
rings={9:(11,16),10:(36,41),7:(61,66),8:(92,97)}
for ga,(r0,r1) in rings.items():
    print(f" Ga{ga}-ringC:",[round(d(ga,rc),2) for rc in range(r0,r1)])
